// function getElement(arr, index) mein array aur index do
// Agar array nahi hai: "Invalid array"
// Agar index out of bounds: "Index out of bounds"
// Warna element return karo

solution:
function getElement(arr, index) {
  if (!Array.isArray(arr)) return "Invalid array"
  if (index < 0 || index >= arr.length) return "Index out of bounds"
  return arr[index]
}
